command:
// ==========================================
// LUNAS WIRKUNG: GEISTERFREUND (ZERZAL)
//
// - genau ein Geist als Ziel
// - Startstufe durch die Spielleitung
// - Verbesserung um QS, maximal Stufe 7
// - Sonderfertigkeit und Effekt mit gemeinsamer Link-ID
// - sichtbarer Effekt vollständig über Block 5
// - keine erfundene Systemänderung
// - Live-Synchronisation der Beziehungsstufe
// - Sonderfertigkeit endet gemeinsam mit dem Effekt
// - Wirkungsende über Block 6
// - gespeichertes Ziel ohne erneutes Target
// - gemeinsame Karte über Block 19.8
// - roter GM-Button „Effekt anwenden“
// - dieselbe Karte wird aktualisiert
// ==========================================


// ============================================================
// === 1 - INIT-MODUS: SYNCHRONISATION UND ITEM-CLEANUP ========
// ============================================================

if (typeof args !== "undefined" && args[0] === "WeckerAufruf") {
    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";

    if (!globalThis.DSK?.UI?.Header || !globalThis.DSK?.Symbol) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (fwMacro?.execute) await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;
    if (!DSK_FW?.UI?.Header || !DSK_FW?.Symbol) {
        return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!");
    }

    const sfName = "Geisterfreund (Zerzal)";
    const stufenTexte = {
        1: "Unstillbarer Hass", 2: "Feindselig", 3: "Abscheu / Ablehnung",
        4: "Abneigung", 5: "Neutral", 6: "Zuneigung", 7: "Vertrauen / Freundschaft"
    };

    const getOwners = actor => Object.entries(actor?.ownership || {})
        .filter(([id, level]) =>
            id !== "default" &&
            Number(level) === CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER &&
            game.users.get(id)
        )
        .map(([id]) => id);

    const ladeActor = async uuid => {
        if (!uuid) return null;
        try {
            const doc = await fromUuid(uuid);
            return doc?.documentName === "Token" ? doc.actor : doc || null;
        } catch {
            return null;
        }
    };

    // +++ 1.1 - VORHANDENE HOOKS ERSETZEN +++++++++++++++++++++

    if (globalThis._dskGeisterfreundItemHook) {
        Hooks.off("updateItem", globalThis._dskGeisterfreundItemHook);
    }

    if (globalThis._dskGeisterfreundEffectHook) {
        Hooks.off("updateActiveEffect", globalThis._dskGeisterfreundEffectHook);
    }

    if (globalThis._dskGeisterfreundDeleteHook) {
        Hooks.off("preDeleteActiveEffect", globalThis._dskGeisterfreundDeleteHook);
    }

    // +++ 1.2 - SONDERFERTIGKEIT → EFFEKT +++++++++++++++++++++

    globalThis._dskGeisterfreundItemHook = Hooks.on(
        "updateItem",
        async (item, changes, options, userId) => {
            if (game.user.id !== userId || options?.dskSync) return;
            if (item.type !== "specialability" || item.name !== sfName) return;
            if (item.getFlag("dsk", "isGeisterfreund") !== true) return;

            const neuerWert = foundry.utils.getProperty(changes, "system.level");
            if (neuerWert === undefined || !Number.isFinite(Number(neuerWert))) return;

            const geistActor = item.parent;
            if (!geistActor) return;

            const stufe = Math.clamp(Math.trunc(Number(neuerWert)), 1, 7);
            const linkId = item.getFlag("dsk", "geisterfreundLinkId");

            const effekt = geistActor.effects.find(eintrag =>
                (eintrag.name || eintrag.label || "") === sfName &&
                eintrag.getFlag("dsk", "isGeisterfreund") === true &&
                eintrag.getFlag("dsk", "geisterfreundLinkId") === linkId
            );

            if (effekt && Number(effekt.getFlag("dsk", "value")) !== stufe) {
                await effekt.update(
                    { "flags.dsk.value": stufe },
                    { dskSync: true }
                );
            }

            const casterActor = await ladeActor(item.getFlag("dsk", "casterUuid"));

            const ownerIds = [...new Set([
                ...game.users.filter(user => user.isGM).map(user => user.id),
                ...getOwners(geistActor),
                ...getOwners(casterActor)
            ])].filter(id => game.users.get(id));

            await ChatMessage.create({
                whisper: ownerIds,
                speaker: { alias: "System" },
                content: `
                    ${DSK_FW.UI.Header(sfName, DSK_FW.Symbol("Zerzal"))}
                    <div class="dskbox2" style="margin-top:10px;">
                        <p style="text-align:center;font-weight:bold;font-size:1.15em;margin-bottom:8px;">
                            Beziehungsänderung
                        </p>
                        <p style="font-size:.95em;line-height:1.35;">
                            Durch Ereignisse hat sich die Beziehungsstufe bei
                            <b>${geistActor.name}</b> verändert.
                            <br><br><b>Neue Stufe:</b> ${stufe}
                            <br><i>Das bedeutet: Das Ziel empfindet
                            <b>${stufenTexte[stufe] || "Unbekannt"}</b>.</i>
                        </p>
                    </div>`
            });
        }
    );

    // +++ 1.3 - EFFEKT → SONDERFERTIGKEIT +++++++++++++++++++++

    globalThis._dskGeisterfreundEffectHook = Hooks.on(
        "updateActiveEffect",
        async (effect, changes, options, userId) => {
            if (game.user.id !== userId || options?.dskSync) return;
            if ((effect.name || effect.label || "") !== sfName) return;
            if (effect.getFlag("dsk", "isGeisterfreund") !== true) return;

            const neuerWert = foundry.utils.getProperty(changes, "flags.dsk.value");
            if (neuerWert === undefined || !Number.isFinite(Number(neuerWert))) return;

            const geistActor = effect.parent;
            if (!geistActor) return;

            const stufe = Math.clamp(Math.trunc(Number(neuerWert)), 1, 7);
            const linkId = effect.getFlag("dsk", "geisterfreundLinkId");

            const sfItem = geistActor.items.find(item =>
                item.type === "specialability" &&
                item.name === sfName &&
                item.getFlag("dsk", "isGeisterfreund") === true &&
                item.getFlag("dsk", "geisterfreundLinkId") === linkId
            );

            if (sfItem && Number(sfItem.system?.level) !== stufe) {
                await sfItem.update(
                    { "system.level": stufe },
                    { dskSync: true }
                );
            }
        }
    );

    // +++ 1.4 - EFFEKTENDE ENTFERNT VERKNÜPFTES ITEM ++++++++++

    globalThis._dskGeisterfreundDeleteHook = Hooks.on(
        "preDeleteActiveEffect",
        async effect => {
            if ((effect.name || effect.label || "") !== sfName) return;
            if (effect.getFlag("dsk", "isGeisterfreund") !== true) return;

            const geistActor = effect.parent;
            const linkId = effect.getFlag("dsk", "geisterfreundLinkId");
            if (!geistActor || !linkId) return;

            const sfItem = geistActor.items.find(item =>
                item.type === "specialability" &&
                item.name === sfName &&
                item.getFlag("dsk", "isGeisterfreund") === true &&
                item.getFlag("dsk", "geisterfreundLinkId") === linkId
            );

            if (sfItem) {
                await sfItem.delete({ dskGeisterfreundEffectEnd: true });
            }
        }
    );

    globalThis._dskGeisterfreundInit = true;
    console.log("Geisterfreund: Synchronisation und Cleanup wurden initialisiert.");
    return;
}


// ============================================================
// === 2 - NORMALE AUSFÜHRUNG =================================
// ============================================================

(async function () {
    const macroUuid = this?.uuid || game.macros.getName("Geisterfreund")?.uuid || null;

    // +++ 2.1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";

    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden ||
        !globalThis.DSK?.Effekt?.CheckTarget ||
        !globalThis.DSK?.EffektEnde?.Register ||
        !globalThis.DSK?.QS?.Ermitteln ||
        !globalThis.DSK?.Token?.Finde ||
        !globalThis.DSK?.Target?.Erstes ||
        !globalThis.DSK?.Target?.Merken ||
        !globalThis.DSK?.Target?.Actor ||
        !globalThis.DSK?.GMAnfrage?.Speichern ||
        !globalThis.DSK?.GMAnfrage?.Finden ||
        !globalThis.DSK?.GMAnfrage?.Lesen ||
        !globalThis.DSK?.GMAnfrage?.Loeschen ||
        !globalThis.DSK?.GabenUI?.GMMakroButton ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);

        if (!fwMacro?.execute) {
            return ui.notifications.error(
                "Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!"
            );
        }

        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Effekt?.Anwenden ||
        !DSK_FW?.Effekt?.CheckTarget ||
        !DSK_FW?.EffektEnde?.Register ||
        !DSK_FW?.QS?.Ermitteln ||
        !DSK_FW?.Token?.Finde ||
        !DSK_FW?.Target?.Erstes ||
        !DSK_FW?.Target?.Merken ||
        !DSK_FW?.Target?.Actor ||
        !DSK_FW?.GMAnfrage?.Speichern ||
        !DSK_FW?.GMAnfrage?.Finden ||
        !DSK_FW?.GMAnfrage?.Lesen ||
        !DSK_FW?.GMAnfrage?.Loeschen ||
        !DSK_FW?.GabenUI?.GMMakroButton ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
        !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
    ) {
        return ui.notifications.error(
            "Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!"
        );
    }

    // +++ 2.2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++

    const gabenName = "Geisterfreund";
    const vollerName = "Geisterfreund (Zerzal)";
    const sfName = vollerName;
    const ahne = "Zerzal";
    const flagKey = "pendingGeisterfreundZerzal";

    const endeKey = "geisterfreundZerzal";
    const endeText =
        "Die geweckten Sympathien verfliegen. Der Geist besinnt sich auf seine wahre Haltung.";

    const zerzalIcon = DSK_FW.Symbol(ahne);

    const stufenTexte = {
        1: "Unstillbarer Hass",
        2: "Feindselig",
        3: "Abscheu / Ablehnung",
        4: "Abneigung",
        5: "Neutral",
        6: "Zuneigung",
        7: "Vertrauen / Freundschaft"
    };

    const stufenErklaerung = Object.entries(stufenTexte)
        .map(([stufe, text]) => `<b>${stufe}</b>: ${text}`)
        .join("<br>");

    const basisBeschreibung =
        "Beeinflusst die Gefühle eines Geistes und verändert dessen Beziehungsstufe.";

    const dauerTextFuerQS = qs =>
        `${qs * 5} Minuten <span style="font-weight:300;font-size:.9em;opacity:.8;">(${qs} QS)</span>`;

    DSK_FW.EffektEnde.Register(
        endeKey,
        vollerName,
        endeText
    );

    // +++ 2.3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++

    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) {
            await actor.unsetFlag("world", "letzteGabenQS");
        }

        if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) {
            await actor.unsetFlag("world", "letzteGabenMessageId");
        }
    };

    const ladeGeist = async zielDaten =>
        zielDaten
            ? await DSK_FW.Target.Actor(zielDaten)
            : null;

    const findeGeisterfreundItem = actor =>
        actor?.items?.find(item =>
            item.type === "specialability" &&
            item.name === sfName
        ) || null;

    const findeGeisterfreundEffekte = actor =>
        (actor?.effects || []).filter(effect =>
            (effect.name || effect.label || "") === vollerName &&
            effect.getFlag("dsk", "isGeisterfreund") === true
        );

    // +++ 2.4 - STARTSTUFE ABFRAGEN +++++++++++++++++++++++++++

    const frageStartstufe = async ({
        geistActor,
        casterName,
        qs
    }) => {
        const vorhandeneSF =
            findeGeisterfreundItem(geistActor);

        const gespeicherteStufe =
            vorhandeneSF
                ? Math.clamp(
                    Number(vorhandeneSF.system?.level) || 4,
                    1,
                    7
                )
                : null;

        const startVal =
            gespeicherteStufe ?? 4;

        const bisherigeStufeHtml =
            gespeicherteStufe !== null
                ? `
                    <div style="margin-bottom:10px;padding:8px 10px;background:rgba(24,148,15,.08);border:1px solid rgba(24,148,15,.35);border-radius:4px;">
                        <p style="margin:0 0 5px;font-weight:bold;">
                            Der Geist wurde bereits früher von Geisterfreund beeinflusst.
                        </p>

                        <p style="margin:0;">
                            Zuletzt gespeichert:
                            <b style="color:#76301b;">
                                ${gespeicherteStufe} – ${stufenTexte[gespeicherteStufe]}
                            </b>
                        </p>
                    </div>
                `
                : `
                    <div style="margin-bottom:10px;padding:8px 10px;background:rgba(118,48,27,.06);border:1px solid rgba(118,48,27,.3);border-radius:4px;">
                        <p style="margin:0;">
                            Für diesen Geist ist noch keine frühere Beziehungsstufe gespeichert.
                        </p>
                    </div>
                `;

        return foundry.applications.api.DialogV2.wait({
            window: {
                title: vollerName
            },

            position: {
                width: 450
            },

            content: `
                <form>
                    <div style="font-family:'Signika',sans-serif;">
                        ${DSK_FW.UI.Header(vollerName, zerzalIcon)}

                        <div class="dskbox2" style="margin-top:10px;">
                            <p style="font-size:.9em;margin-bottom:8px;">
                                Ziel: <b>${geistActor.name}</b> |
                                Gewirkt von: <b>${casterName}</b> |
                                QS: <b>${qs}</b>
                            </p>

                            <hr>

                            ${bisherigeStufeHtml}

                            <div style="margin-bottom:10px;padding:8px 10px;background:rgba(118,48,27,.08);border-radius:4px;">
                                <p style="margin:0;">
                                    <b>Regel:</b>
                                    Die Beziehungsstufe liegt normalerweise bei
                                    <b>4 oder 5</b>.
                                </p>
                            </div>

                            <div style="display:flex;justify-content:space-between;align-items:center;margin:8px 0;">
                                <label style="font-weight:bold;">
                                    Start-Stufe (1–7):
                                </label>

                                <input
                                    type="number"
                                    name="startLevel"
                                    value="${startVal}"
                                    min="1"
                                    max="7"
                                    style="width:80px;text-align:center;"
                                >
                            </div>

                            <hr>

                            <p style="font-size:.85em;line-height:1.3;">
                                <b>Beziehungsstufen:</b>
                                <br>
                                ${stufenErklaerung}
                            </p>
                        </div>
                    </div>
                </form>
            `,

            buttons: [
                {
                    action: "ok",
                    label: "Gabe anwenden",
                    icon: "fas fa-magic",
                    default: true,

                    callback: event => {
                        const form =
                            event.target.closest("form");

                        const eingabe =
                            Number(
                                new FormData(form).get("startLevel")
                            );

                        return Math.clamp(
                            Math.trunc(
                                Number.isFinite(eingabe)
                                    ? eingabe
                                    : startVal
                            ),
                            1,
                            7
                        );
                    }
                },
                {
                    action: "cancel",
                    label: "Abbrechen",
                    icon: "fas fa-times",
                    callback: () => null
                }
            ],

            rejectClose: false
        });
    };

    // +++ 2.5 - EFFEKT 1:1 NACH ANLEITEN ÜBER BLOCK 5 ++++++++++++

const wendeGeisterfreundAn = async ({
    casterActor, casterName, geistActor, geistName,
    qs, startStufe, neueStufe
}) => {
    if (!casterActor || !geistActor) return null;

    const linkId = foundry.utils.randomID();
    const dauerMinuten = qs * 5;

    const beschreibung =
        `<b>${casterName}</b> beeinflusst die Gefühle von <b>${geistName}</b>.` +
        `<br><br><b>Startstufe:</b> ${startStufe}` +
        `<br><b>Verbesserung:</b> +${qs} (QS)` +
        `<br><b>Neue Stufe:</b> ${neueStufe} (${stufenTexte[neueStufe]})` +
        `<br><br><b>Beziehungsstufen:</b><br>` +
        Object.entries(stufenTexte)
            .map(([stufe, text]) => `${stufe}: ${text}`)
            .join("<br>") +
        `<br><br><b>Wirkungsdauer:</b> ${dauerMinuten} Minuten`;

    // Alte Effekte dieser Gabe entfernen.
    const alteEffekte = findeGeisterfreundEffekte(geistActor);

    if (alteEffekte.length) {
        await geistActor.deleteEmbeddedDocuments(
            "ActiveEffect",
            alteEffekte.map(effect => effect.id)
        );
    }

    // Alte Sonderfertigkeit entfernen.
    const alteItems = geistActor.items.filter(item =>
        item.type === "specialability" &&
        item.name === sfName
    );

    if (alteItems.length) {
        await geistActor.deleteEmbeddedDocuments(
            "Item",
            alteItems.map(item => item.id),
            { dskGeisterfreundReplace: true }
        );
    }

    let sonderfertigkeit = null;
    let erzeugterEffekt = null;

    try {
        const erstellteItems = await geistActor.createEmbeddedDocuments("Item", [{
            name: sfName,
            type: "specialability",
            img: zerzalIcon,

            flags: {
                dsk: {
                    isGeisterfreund: true,
                    casterUuid: casterActor.uuid,
                    geisterfreundLinkId: linkId
                }
            },

            system: {
                level: neueStufe,
                max: 7,

                rule: Object.entries(stufenTexte)
                    .map(([stufe, text]) => `${stufe}: ${text}`)
                    .join("<br>"),

                description: {
                    value: beschreibung
                }
            }
        }]);

        sonderfertigkeit = erstellteItems?.[0] || null;

        if (!sonderfertigkeit) {
            throw new Error("Die Sonderfertigkeit konnte nicht angelegt werden.");
        }

        /*
         * Effektanlage in derselben Form wie bei Anleiten:
         *
         * skills + key + formel werden an Block 5 übergeben.
         * Block 5 erzeugt daraus den tatsächlichen Change sowie:
         * type, img, icon, showIcon, disabled und transfer.
         */

        erzeugterEffekt = await DSK_FW.Effekt.Anwenden({
            name: vollerName,
            ahne,

            beschreibung,

            gabeZiel: "geist",
            qs,

            skills: ["flags.dsk.geisterfreundStufe"],
            key: "flags.dsk.geisterfreundStufe",
            formel: String(neueStufe),

            ziel: geistActor,

            duration: {
                seconds: dauerMinuten * 60,
                startTime: game.time.worldTime
            },

            flags: {
                dsk: {
                    isGeisterfreund: true,
                    casterUuid: casterActor.uuid,
                    casterName,
                    geistUuid: geistActor.uuid,
                    geistName,
                    geisterfreundLinkId: linkId,
                    value: neueStufe,
                    max: 7,

                    wirkungsende: {
                        sfName: endeKey,
                        basisEffektName: vollerName,
                        beschreibungFuerEnde: endeText
                    }
                }
            }
        });

        if (!erzeugterEffekt) {
            throw new Error("Block 5 konnte den Geisterfreund-Effekt nicht anlegen.");
        }

        // Wie bei Anleiten den tatsächlich erzeugten Effektwert prüfen.
        const korrekterBeziehungswert =
            (erzeugterEffekt.changes || []).some(change =>
                change.key === "flags.dsk.geisterfreundStufe" &&
                Number(change.mode) === 2 &&
                Number(change.value) === neueStufe
            );

        const effektErfolgreich =
            (erzeugterEffekt.name || erzeugterEffekt.label || "") === vollerName &&
            erzeugterEffekt.getFlag("dsk", "isGeisterfreund") === true &&
            erzeugterEffekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
            erzeugterEffekt.getFlag("dsk", "geisterfreundLinkId") === linkId &&
            Number(erzeugterEffekt.getFlag("dsk", "value")) === neueStufe &&
            Number(erzeugterEffekt.getFlag("dsk", "max")) === 7 &&
            korrekterBeziehungswert;

        const itemErfolgreich =
            sonderfertigkeit.getFlag("dsk", "isGeisterfreund") === true &&
            sonderfertigkeit.getFlag("dsk", "casterUuid") === casterActor.uuid &&
            sonderfertigkeit.getFlag("dsk", "geisterfreundLinkId") === linkId &&
            Number(sonderfertigkeit.system?.level) === neueStufe;

        if (!effektErfolgreich || !itemErfolgreich) {
            throw new Error(
                "Effekt und Sonderfertigkeit wurden nicht vollständig verknüpft."
            );
        }

        return {
            effekt: erzeugterEffekt,
            sonderfertigkeit,
            beschreibung,
            linkId
        };

    } catch (error) {
        console.error("Geisterfreund: Anlage fehlgeschlagen.", {
            casterActor: casterActor.name,
            geistActor: geistActor.name,
            linkId,
            error
        });

        if (
            erzeugterEffekt &&
            geistActor.effects.get(erzeugterEffekt.id)
        ) {
            await erzeugterEffekt
                .delete({ dskGeisterfreundEffectFailed: true })
                .catch(() => {});
        }

        if (
            sonderfertigkeit &&
            geistActor.items.get(sonderfertigkeit.id)
        ) {
            await sonderfertigkeit
                .delete({ dskGeisterfreundEffectFailed: true })
                .catch(() => {});
        }

        return null;
    }
};

    // +++ 2.6 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++

    const verarbeiteAnfrage = async (
        casterActor,
        daten
    ) => {
        if (
            !casterActor ||
            !daten ||
            !game.user.isGM
        ) {
            return false;
        }

        if (
            daten.casterUuid &&
            daten.casterUuid !== casterActor.uuid
        ) {
            ui.notifications.warn(
                "Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum wirkenden Akteur."
            );

            return false;
        }

        if (
            daten.sceneId &&
            daten.sceneId !== canvas.scene?.id
        ) {
            ui.notifications.warn(
                `Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`
            );

            return false;
        }

        const geistActor =
            await ladeGeist(daten.ziel);

        const geistName =
            daten.ziel?.name ||
            geistActor?.name ||
            "Unbekannter Geist";

        const casterName =
            daten.casterName ||
            DSK_FW.ResolveTokenName(casterActor);

        const qs =
            Math.max(
                1,
                Math.floor(
                    Number(daten.qs) || 1
                )
            );

        const dauerText =
            daten.dauerText ||
            dauerTextFuerQS(qs);

        if (!geistActor) {
            await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
                messageId:
                    daten.messageId,

                gabenName:
                    vollerName,

                ahne,
                beschreibung:
                    basisBeschreibung,

                wirkender:
                    casterName,

                ziele:
                    [],

                misserfolge: [{
                    name:
                        geistName,

                    grund:
                        "Zielakteur wurde nicht gefunden"
                }],

                dauerText,
                erfolgreich:
                    false
            });

            return true;
        }

        if (
            !DSK_FW.Effekt.CheckTarget(
                geistActor,
                "geist"
            )
        ) {
            await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
                messageId:
                    daten.messageId,

                gabenName:
                    vollerName,

                ahne,
                beschreibung:
                    basisBeschreibung,

                wirkender:
                    casterName,

                ziele:
                    [],

                misserfolge: [{
                    name:
                        geistName,

                    grund:
                        "Kein Geist"
                }],

                dauerText,
                erfolgreich:
                    false
            });

            return true;
        }

        const dialogResult =
            await frageStartstufe({
                geistActor,
                casterName,
                qs
            });

        // Abbrechen lässt die Anfrage bestehen.
        if (dialogResult === null) {
            return false;
        }

        const startStufe =
            Math.clamp(
                Number(dialogResult) || 4,
                1,
                7
            );

        const neueStufe =
            Math.min(
                7,
                startStufe + qs
            );

        const ergebnis =
            await wendeGeisterfreundAn({
                casterActor,
                casterName,
                geistActor,
                geistName,
                qs,
                startStufe,
                neueStufe
            });

        const erfolgreich =
            Boolean(ergebnis);

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId:
                daten.messageId,

            gabenName:
                vollerName,

            ahne,

            beschreibung:
                erfolgreich
                    ? ergebnis.beschreibung
                    : basisBeschreibung,

            wirkender:
                casterName,

            ziele:
                erfolgreich
                    ? [{
                        name:
                            `${geistName} – Stufe ${neueStufe}: ${stufenTexte[neueStufe]}`,

                        rolle:
                            "Beeinflusster Geist"
                    }]
                    : [],

            misserfolge:
                erfolgreich
                    ? []
                    : [{
                        name:
                            geistName,

                        grund:
                            "Effekt oder Sonderfertigkeit konnte nicht vollständig angelegt werden"
                    }],

            dauerText,
            erfolgreich
        });

        if (!erfolgreich) {
            ui.notifications.error(
                "Luna sagt 🌙: Geisterfreund konnte nicht vollständig angewendet werden!"
            );

            // Anfrage wurde vollständig verarbeitet.
            return true;
        }

        ui.notifications.info(
            `Luna sagt 🌙: Die Beziehungsstufe von ${geistName} wurde auf ${neueStufe} erhöht.`
        );

        return true;
    };

    // +++ 2.7 - GM-MODUS ++++++++++++++++++++++++++++++++++++++

    if (game.user.isGM) {
        const anfragen =
            DSK_FW.GMAnfrage.Finden(flagKey);

        if (anfragen.length) {
            for (const anfrageActor of anfragen) {
                const daten =
                    DSK_FW.GMAnfrage.Lesen(
                        anfrageActor,
                        flagKey
                    );

                if (!daten) continue;

                const verarbeitet =
                    await verarbeiteAnfrage(
                        anfrageActor,
                        daten
                    );

                if (verarbeitet) {
                    await DSK_FW.GMAnfrage.Loeschen(
                        anfrageActor,
                        flagKey
                    );
                }
            }

            return;
        }
    }

    // +++ 2.8 - WIRKENDER UND QS ++++++++++++++++++++++++++++++

    let casterActor =
        canvas.tokens.controlled[0]?.actor ||
        game.user.character ||
        null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables
                .map(token => token.actor)
                .find(actor =>
                    actor?.getFlag(
                        "world",
                        "letzteGabenQS"
                    ) !== undefined
                ) ||

            game.actors.find(actor =>
                actor.getFlag(
                    "world",
                    "letzteGabenQS"
                ) !== undefined
            ) ||

            null;
    }

    if (!casterActor) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!"
        );
    }

    if (
        !game.user.isGM &&
        !casterActor.isOwner
    ) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
        );
    }

    const casterToken =
        DSK_FW.Token.Finde(casterActor);

    if (!casterToken) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Konnte den Token des Wirkenden nicht finden!"
        );
    }

    const casterName =
        DSK_FW.ResolveTokenName(casterActor);

    const qs =
        DSK_FW.QS.Ermitteln({
            actor:
                casterActor,

            gabenName,

            suchbegriffe: [
                "Geisterfreund Probe",
                "Geisterfreund"
            ],

            testDataObj:
                typeof testData !== "undefined"
                    ? testData
                    : null,

            fallback:
                0,

            protokollieren:
                true
        });

    if (qs <= 0) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName:
                vollerName,

            ahne,

            beschreibung:
                "Die Gefühle des Geistes konnten nicht beeinflusst werden.",

            wirkender:
                casterName,

            ziele:
                [],

            misserfolge: [{
                name:
                    casterName,

                grund:
                    "Probe fehlgeschlagen"
            }],

            gmBereich:
                false,

            angewendet:
                true,

            erfolgreich:
                false,

            anfragenderUserId:
                game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 2.9 - ZIEL PRÜFEN UND SPEICHERN +++++++++++++++++++++

    const targetToken =
        DSK_FW.Target.Erstes();

    if (!targetToken?.actor) {
        await raeumeQSAuf(casterActor);

        return ui.notifications.warn(
            "Luna sagt 🌙: Bitte markiere zuerst den Geist als Target!"
        );
    }

    const geistActor =
        targetToken.actor;

    const geistName =
        targetToken.name ||
        geistActor.name ||
        "Unbekannter Geist";

    if (
        !DSK_FW.Effekt.CheckTarget(
            geistActor,
            "geist"
        )
    ) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName:
                vollerName,

            ahne,
            beschreibung:
                basisBeschreibung,

            wirkender:
                casterName,

            ziele:
                [],

            misserfolge: [{
                name:
                    geistName,

                grund:
                    "Kein Geist"
            }],

            dauerText:
                dauerTextFuerQS(qs),

            gmBereich:
                false,

            angewendet:
                true,

            erfolgreich:
                false,

            anfragenderUserId:
                game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    const zielDaten =
        DSK_FW.Target.Merken(targetToken);

    if (!zielDaten) {
        await raeumeQSAuf(casterActor);

        return ui.notifications.error(
            "Luna sagt 🌙: Der ausgewählte Geist konnte nicht gespeichert werden!"
        );
    }

    // +++ 2.10 - GEMEINSAME KARTE + ROTER GM-BUTTON ++++++++++

    const dauerText =
        dauerTextFuerQS(qs);

    const gmLink =
        DSK_FW.GabenUI.GMMakroButton(
            macroUuid,
            "Effekt anwenden",
            "Das Makro muss durch die Spielleitung ausgeführt werden."
        );

    const nachricht =
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName:
                vollerName,

            ahne,

            beschreibung:
                basisBeschreibung,

            wirkender:
                casterName,

            ziele: [{
                name:
                    geistName,

                rolle:
                    "Ziel-Geist"
            }],

            misserfolge:
                [],

            dauerText,
            gmLink,

            gmBereich:
                !game.user.isGM,

            anfragenderUserId:
                game.user.id
        });

    if (!nachricht) {
        await raeumeQSAuf(casterActor);

        return ui.notifications.error(
            "Luna sagt 🌙: Die Geisterfreund-Karte konnte nicht erstellt werden!"
        );
    }

    // +++ 2.11 - ANFRAGEDATEN +++++++++++++++++++++++++++++++++

    const anfrageDaten = {
        casterUuid:
            casterActor.uuid,

        casterName,

        casterTokenId:
            casterToken.id,

        casterTokenUuid:
            casterToken.document?.uuid ||
            casterToken.uuid ||
            null,

        ziel:
            zielDaten,

        qs,
        dauerText,

        sceneId:
            canvas.scene?.id ||
            null,

        requestedByUserId:
            game.user.id,

        messageId:
            nachricht.id,

        macroUuid,

        erstellt:
            Date.now()
    };

    // +++ 2.12 - GM DIREKT ODER ANFRAGE SPEICHERN +++++++++++++

    if (game.user.isGM) {
        await verarbeiteAnfrage(
            casterActor,
            anfrageDaten
        );

        await raeumeQSAuf(casterActor);
        return;
    }

    await DSK_FW.GMAnfrage.Speichern(
        casterActor,
        flagKey,
        anfrageDaten
    );

    // +++ 2.13 - QS AUFRÄUMEN +++++++++++++++++++++++++++++++++

    await raeumeQSAuf(casterActor);

    ui.notifications.info(
        "Luna sagt 🌙: Geisterfreund wurde bei der Spielleitung beantragt."
    );

}).call(this);
